(6613901, 987265, 141542, '<td valign="top">Great composition.  I don''t know how I feel about the crop, but an awesome shot all the same.</td>', 'Great composition.  I don''t know how I feel about the crop, but an awesome shot all the same.', '2011-12-08 03:40:09.000000', NULL, 1),
(6613903, 986627, 141542, '<td valign="top">Love this, and what a perfect way to embrace the mission statement for this challenge.  A surprisingly tasteful, contemporary, and bearable use of selective color in 2011.</td>', 'Love this, and what a perfect way to embrace the mission statement for this challenge.  A surprisingly tasteful, contemporary, and bearable use of selective color in 2011.', '2011-12-08 03:40:54.000000', NULL, 1),
(6613905, 986712, 141542, '<td valign="top">Sharp, current, and screams freedom, especially with the title to help.  Perhaps actual free running (as opposed to this stunt) would have been better, but it''s still excellent.</td>', 'Sharp, current, and screams freedom, especially with the title to help.  Perhaps actual free running (as opposed to this stunt) would have been better, but it''s still excellent.', '2011-12-08 03:41:58.000000', NULL, 1),
(6613906, 987282, 141542, '<td valign="top">Good use of an s-curve, but not a single thing seems to be sharp.  Looks a bit dark also.</td>', 'Good use of an s-curve, but not a single thing seems to be sharp.  Looks a bit dark also.', '2011-12-08 03:43:03.000000', NULL, 1),
(6613907, 987178, 141542, '<td valign="top">Flat light and no context.</td>', 'Flat light and no context.', '2011-12-08 03:43:57.000000', NULL, 1),
(6613909, 987368, 141542, '<td valign="top">Seems underexposed, and at an angle which doesn''t do anything much justice other than a spray can.  Interesting concept, though.<br/></td>', 'Seems underexposed, and at an angle which doesn''t do anything much justice other than a spray can.  Interesting concept, though.', '2011-12-08 03:45:14.000000', NULL, 1),
(6613910, 987370, 141542, '<td valign="top">Minimal editing?</td>', 'Minimal editing?', '2011-12-08 03:45:29.000000', NULL, 1),
(6613912, 987095, 141542, '<td valign="top">Unfortunately blurry and a bit voyeuristic.</td>', 'Unfortunately blurry and a bit voyeuristic.', '2011-12-08 03:46:09.000000', NULL, 1),
(6613914, 987145, 141542, '<td valign="top">Pretty lackluster for a subject as epic as freedom.</td>', 'Pretty lackluster for a subject as epic as freedom.', '2011-12-08 03:47:44.000000', NULL, 1),
(6613916, 987110, 141542, '<td valign="top">Love, love, love it.  Great capture, great angle, and the teacher''s pet right in the bottom left takes the cake.  Well done.</td>', 'Love, love, love it.  Great capture, great angle, and the teacher''s pet right in the bottom left takes the cake.  Well done.', '2011-12-08 03:48:41.000000', NULL, 1),
